            // Put the shipped rows back next to the edits.
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-melee', 'Armas Brancas', 'Físicas', 'Permite o manejo ágil e letal de armas portáteis focadas no combate corpo a corpo, englobando desde facas e espadas até correntes, machados e estacas de caçadores.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-firearms', 'Armas de Fogo', 'Físicas', 'Engloba a manutenção (limpeza e destravamento), a recarga ágil e o disparo de precisão de armamentos que usam gatilho, passando por pistolas, fuzis e lançadores de granada ou bestas.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-athletics', 'Atletismo', 'Físicas', 'Define a capacidade de correr, saltar, nadar e fazer acrobacias ou manobras de parkour. Também pode ser usada de forma defensiva como esquiva em substituição às habilidades de ataque durante combates.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-brawl', 'Briga', 'Físicas', 'A arte pura do combate desarmado para lutar e nocautear. Abrange desde as táticas sujas de brigas de rua até estilos formais e marciais usando punhos, chutes ou golpes de garras.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-drive', 'Condução', 'Físicas', 'A capacidade de pilotar e controlar os mais diversos veículos com destreza e segurança em velocidades extremas. É uma habilidade vital para fugas, perseguições urbanas e manobras sob intenso estresse.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-stealth', 'Furtividade', 'Físicas', 'O talento imperceptível do caçador para se esgueirar pelas sombras, evitar rondas de segurança, esconder-se do olhar humano e rastrear ou perseguir presas de forma sorrateira.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-larceny', 'Ladroagem', 'Físicas', 'Intimidade prática com invasões. Permite bater carteiras na rua, abrir cofres antigos ou eletrônicos, forçar cadeados e fechaduras, fazer ligações diretas em carros e burlar alarmes de invasão domiciliar.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-craft', 'Ofícios', 'Físicas', 'Representa a criatividade e a execução de trabalhos artesanais do personagem, seja esculpindo, costurando e forjando armas, ou até mesmo estruturando armadilhas e erguendo o próprio refúgio.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-survival', 'Sobrevivência', 'Físicas', 'Define a adaptabilidade em áreas selvagens rurais ou nas entranhas selva urbana. Facilita caçar fora das metrópoles, montar abrigos naturais de emergência e rastrear perigos como lobisomens.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-animal-ken', 'Empatia com Animais', 'Sociais', 'Concede a aptidão para pacificar, se aproximar, treinar e prever os humores dos animais de forma que eles não fujam ou ataquem instintivamente o personagem devido à sua condição morta-viva.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-etiquette', 'Etiqueta', 'Sociais', 'Compreensão das normas, regras de deferência e dos costumes adequados a cada contexto da sociedade. Evita gafes mortais nas cortes dos Príncipes ou entre as elites de alto poder aquisitivo no mundo humano.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-intimidation', 'Intimidação', 'Sociais', 'O instinto de subjugar outras mentes de forma brutal através do poder da opressão, olhares fixos, xingamentos ríspidos ou da promessa de coerção e extrema violência física.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-leadership', 'Liderança', 'Sociais', 'A capacidade política de guiar grupos de mortais e vampiros de forma cativante. É voltada a organizar manifestações, elevar moralmente os aliados e liderar bandos em campos de guerra violentos.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-streetwise', 'Manha', 'Sociais', 'O domínio nativo sobre as complexas regras e códigos do submundo local. Facilita a comunicação nas ruas por pichações de gangue, indica onde adquirir suprimentos vitais no mercado negro ou recrutar criminosos.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-performance', 'Performance', 'Sociais', 'A expressão magnética e o virtuosismo das belas artes, englobando a apresentação cênica, dança, oratória, poesia e comédia para entreter, emocionar ou impressionar espectadores.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-persuasion', 'Persuasão', 'Sociais', 'O dom prático de argumentar com eloquência em negociações e barganhas, convencendo o outro ouvidor de que a intenção do vampiro — de uma assinatura de acordo a um gole de sangue — não representa perigo e faz sentido.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-insight', 'Sagacidade', 'Sociais', 'Atua como um dom investigativo empático na percepção humana, decifrando intenções escondidas, fobias ocultas, mentiras escancaradas ou nuances da linguagem não-verbal nos inimigos.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-subterfuge', 'Subterfúgio', 'Sociais', 'O talento indispensável para forjar redes de enganos duradouras e proteger o disfarce pessoal, seduzindo, contando falsidades de maneira fria e escondendo crimes atrás de uma máscara de completa inocência.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-science', 'Ciência', 'Mentais', 'Estudo focado das leis lógicas e das engrenagens universais. Envolve conhecimento laboratorial prático ou acadêmico em química, genoma genético molecular, matemática, física e engenharia pesada.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-academics', 'Erudição', 'Mentais', 'Representa uma instrução superior adquirida via dedicação acadêmica ou em mentorias ao longo das eras. Rege as áreas de humanas, focando em interpretação de história de arte, jornalismo, literatura e teologia profunda.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-finance', 'Finanças', 'Mentais', 'Habilidade imperativa aos Ventrue modernos voltada a avaliar obras de arte, administrar grandes portfólios corporativos, manipular transações ilegais invisíveis e criar empresas para lavar montanhas de dinheiro.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-investigation', 'Investigação', 'Mentais', 'A proficiência forense focada em notar coisas fora do padrão mundano. É vital para caçar indivíduos desaparecidos, ler cenas de assassinatos com olhar criminal e interrogar pistas sem levantar suspeitas do alvo real.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-medicine', 'Medicina', 'Mentais', 'Conhecimento vital ou traumatológico usado clinicamente para diagnosticar mortes e prever anomalias de sangue e veias. Na prática, é aplicada em cirurgias severas e curativos de urgência que estabilizam danos agravados na saúde de mortais.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-occult', 'Ocultismo', 'Mentais', 'A sabedoria essencial sobre todos os aspectos do Mundo das Trevas, englobando táticas contra fantasmas, lobisomens, parapsicologia esotérica e até conhecimentos obscuros e proibidos como Magia de Sangue e textos nodistas.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-awareness', 'Percepção', 'Mentais', 'O uso atento, focado ou automático de instintos corporais para vigiar os arredores. Detecta desde pistas visuais em cantos escuros até aproximações sorrateiras, odores estranhos persistentes ou emboscadas invisíveis.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-politics', 'Política', 'Mentais', 'Compreensão técnica da diplomacia e da mecânica dos governos de gabinete e sindicatos na prefeitura. Envolve rastrear esquemas de poder da Mídia, dominar cargos burocráticos e jogar a guerra dos tronos nas diferentes Seitas cainitas e mortais.');");
            migrationBuilder.Sql(@"INSERT OR IGNORE INTO ""SkillCatalog"" (""Id"", ""Name"", ""Group"", ""Description"") VALUES ('skill-technology', 'Tecnologia', 'Mentais', 'A capacidade pragmática ou engenhosa no mundo contemporâneo para lidar com inovações. Envolve operações furtivas como hackear servidores corporativos em rede local, sumir na vigilância cibernética de metrópoles, montar computadores blindados e decodificar dados restritos.');");
